const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const clipId = body.clip_id;
if (!clipId) throw new Error('LOOM_REVIEW_INVALID: missing clip_id');

const validDecisions = ['approve', 'reject', 'hold'];
const rawDecision = body.decision;
if (!validDecisions.includes(rawDecision)) {
  throw new Error('LOOM_REVIEW_INVALID: decision must be approve|reject|hold, got ' + JSON.stringify(rawDecision));
}

const tenantId = body.tenant_id || null;
if (!tenantId) throw new Error('LOOM_REVIEW_INVALID: missing tenant_id');
const assetVersion = body.asset_version || null;
if (!assetVersion) throw new Error('LOOM_REVIEW_INVALID: missing asset_version');
const validStages = ['moment', 'final_publication'];
if (!validStages.includes(body.review_stage)) {
  throw new Error('LOOM_REVIEW_INVALID: review_stage must be moment|final_publication, got ' + JSON.stringify(body.review_stage));
}

let decision = rawDecision;
let finalStatus = null;
let reviewerInstructions = body.reviewer_instructions || null;
let rejectionCategory = body.rejection_category || null;

if (rawDecision === 'reject' && !rejectionCategory) {
  throw new Error('LOOM_REVIEW_INVALID: rejection_category is required for reject');
}

if (body.action === 'retry_failed_step') {
  decision = 'hold';
  finalStatus = 'retry_requested';
  reviewerInstructions = (reviewerInstructions ? reviewerInstructions + '; ' : '') + 'retry smallest failed operation once, then hold';
}

if (!finalStatus) {
  finalStatus = decision === 'approve' ? 'approved' : (decision === 'reject' ? 'rejected' : 'on_hold');
}

const reviewPayload = {
  tenant_id: tenantId,
  clip_id: clipId,
  asset_version: assetVersion,
  review_stage: body.review_stage,
  asset_url: body.asset_url || body.preview_url || null,
  reviewer: body.reviewer || 'bryan',
  decision: decision,
  rejection_category: (decision === 'reject') ? rejectionCategory : null,
  reviewer_instructions: reviewerInstructions,
  final_status: finalStatus
};

return [{ json: { review_payload: reviewPayload, publication_enabled: false } }];

const persisted = $json;
const hasError = !!persisted.error;
return [{ json: {
  persisted: !hasError,
  clip_id: persisted.clip_id || ($('Validate Review Decision').item.json.review_payload && $('Validate Review Decision').item.json.review_payload.clip_id) || null,
  decision: (persisted.decision) || ($('Validate Review Decision').item.json.review_payload && $('Validate Review Decision').item.json.review_payload.decision) || null,
  final_status: persisted.final_status || null,
  publication_enabled: false,
  note: 'Durable decision saved. Publication is NOT triggered by this workflow.'
} }];
